use std::path::PathBuf;

use driver::settings::Settings;

const HEADER: &str = "# default_config.toml
#
# Source of truth for default settings. Every key in this file is at its
# default value and is commented out. Uncomment any line to make it explicit.
#
# Generated by `cargo run --bin gen-default-config`. Do not hand-edit \u{2014} edits
# are lost on regeneration. Configure the driver by editing your XDG config at
# `~/.config/maschine-mikro-mk3-driver/config.toml` instead (once roadmap \u{00a7}1
# ships) or by passing `-c <path>` on the CLI today.
#
# Pads keyed 0..15 (top-left to bottom-right).
# Buttons keyed by snake_case names from the `Buttons` enum:
#   maschine, star, browse, volume, swing, tempo, plugin, sampling,
#   left, right, pitch, mod, perform, notes, group, auto,
#   lock, note_repeat, restart, erase, tap, follow, play, rec,
#   stop, shift, fixed_vol, pad_mode, keyboard, chords, step, scene,
#   pattern, events, variation, duplicate, select, solo, mute,
#   encoder_press, encoder_touch.
";

pub fn render_default_config() -> String {
    let body =
        toml::to_string_pretty(&Settings::default()).expect("Settings::default must serialize");

    let mut out = String::with_capacity(HEADER.len() + body.len() * 2);
    out.push_str(HEADER);
    out.push('\n');

    for line in body.lines() {
        if line.is_empty() || line.starts_with('[') {
            out.push_str(line);
        } else {
            out.push_str("# ");
            out.push_str(line);
        }
        out.push('\n');
    }
    out
}

fn default_config_toml_path() -> PathBuf {
    // CARGO_MANIFEST_DIR is the driver crate. Workspace root is two levels up.
    let manifest_dir = env!("CARGO_MANIFEST_DIR");
    PathBuf::from(manifest_dir).join("../../default_config.toml")
}

fn main() {
    let target = std::env::args()
        .nth(1)
        .map(PathBuf::from)
        .unwrap_or_else(default_config_toml_path);
    let rendered = render_default_config();
    std::fs::write(&target, rendered).unwrap_or_else(|err| {
        panic!("failed to write {}: {err}", target.display());
    });
    eprintln!("wrote {}", target.display());
}

#[cfg(test)]
mod tests {
    use super::*;
    use driver::settings::PartialSettings;

    #[test]
    fn default_config_toml_is_up_to_date() {
        let rendered = render_default_config();
        let path = default_config_toml_path();
        let on_disk = std::fs::read_to_string(&path)
            .unwrap_or_else(|err| panic!("expected {} to exist: {err}", path.display()));
        assert_eq!(
            on_disk, rendered,
            "default_config.toml is stale. Run `cargo run --bin gen-default-config`."
        );
    }

    #[test]
    fn uncommented_default_config_round_trips_to_settings_default() {
        let path = default_config_toml_path();
        let on_disk = std::fs::read_to_string(&path)
            .unwrap_or_else(|err| panic!("expected {} to exist: {err}", path.display()));
        // Strip leading "# " on each non-section body line. Drop the file's
        // header docstring (lines before the first section header).
        let mut stripped = String::with_capacity(on_disk.len());
        let mut seen_section = false;
        for line in on_disk.lines() {
            if line.starts_with('[') {
                seen_section = true;
                stripped.push_str(line);
            } else if seen_section && line.starts_with("# ") {
                stripped.push_str(&line[2..]);
            } else if !seen_section {
                // header / docstring — skip
            } else {
                stripped.push_str(line);
            }
            stripped.push('\n');
        }

        // Parse as Settings directly: both Settings and PartialSettings now use
        // the same integer-keyed map format for pads ([pads.0], [pads.1], …),
        // so the generated TOML is compatible with both paths.
        let parsed: Settings =
            toml::from_str(&stripped).expect("uncommented config must parse as Settings");
        assert_eq!(parsed, Settings::default());
        // Also verify the PartialSettings path works for the scalar sections.
        let partial: PartialSettings =
            toml::from_str("[global]\n[hardware]\n[bridge]\n").expect("empty partial must parse");
        let merged = Settings::default().merge_overrides(partial);
        assert_eq!(merged, Settings::default());
    }
}
